	// A float target, so the picture read back is the light the shader computed, unquantised.
	static constexpr acm::Format kColourFormat = acm::Format::R32G32B32A32_Sfloat;

	namespace detail
	{
		void copyMatrix(const math::Mat4d& m, float (&out)[16])
		{
			for (math::length_t c = 0; c < 4; ++c)
			{
				for (math::length_t r = 0; r < 4; ++r)
					out[4 * c + r] = float(m[c][r]);
			}
		}

		acm::DescriptorSet sceneSet(const RendererState& renderer, const SceneState& scene, std::size_t material, const acm::Buffer& frame)
		{
			acm::DescriptorSet set = renderer.device->createDescriptorSet(renderer.sceneLayout);
			if (!set.valid())
				return set;
			const std::size_t texture = scene.materialTextures[material];
			set.setBuffer(0, frame);
			set.setDynamicBuffer(1, scene.objects, sizeof(ObjectConstants));
			set.setBuffer(2, scene.materials[material]);
			set.setTexture(3, texture < scene.textures.size() ? scene.textures[texture] : scene.white, renderer.sampler);
			set.setBuffer(4, scene.lights);
			return set;
		}

		FrameConstants frameConstants(const SceneState& scene, const View& view, bool encode, const Grid* grid)
		{
			FrameConstants frame{};
			const math::Mat4d clip = clipFromCamera(view);
			copyMatrix(clip * view.worldFromCamera.inverse().matrix(), frame.clipFromWorld);
			for (math::length_t r = 0; r < 4; ++r)
				frame.cameraAxis[r] = float(clip[2][r]);
			const math::Vec3d& eye = view.worldFromCamera.translation();
			frame.eye[0] = float(eye.x);
			frame.eye[1] = float(eye.y);
			frame.eye[2] = float(eye.z);
			frame.eye[3] = 1.0f;
			frame.ambient[0] = scene.ambient.r;
			frame.ambient[1] = scene.ambient.g;
			frame.ambient[2] = scene.ambient.b;
			frame.lightCount = scene.lightCount;
			frame.encode = encode ? 1u : 0u;
			if (grid)
			{
				frame.grid = 1u;
				const auto put = [](float (&out)[4], const math::Vec3d& xyz, double w)
				{
					out[0] = float(xyz.x);
					out[1] = float(xyz.y);
					out[2] = float(xyz.z);
					out[3] = float(w);
				};
				put(frame.gridOrigin, grid->origin, grid->spacing);
				put(frame.gridU, grid->u, grid->extent.x);
				put(frame.gridV, grid->v, grid->extent.y);
				put(frame.gridMinor, {grid->minor.r, grid->minor.g, grid->minor.b}, double(grid->majorEvery));
				put(frame.gridMajor, {grid->major.r, grid->major.g, grid->major.b}, 0.0);
			}
			return frame;
		}

		acm::Error recordScene(acm::CommandBuffer& cmd, const acm::Pipeline& pipeline, const SceneState& scene,
							   const std::vector<acm::DescriptorSet>& sets)
		{
			if (acm::Error error = cmd.bindPipeline(pipeline))
				return error;
			for (const SceneState::Draw& draw : scene.draws)
			{
				cmd.bindDescriptorSet(pipeline, sets[draw.material], draw.objectOffset);
				cmd.bindVertexBuffer(scene.meshes[draw.mesh].vertices);
				cmd.bindIndexBuffer(scene.meshes[draw.mesh].indices);
				if (acm::Error error = cmd.drawIndexed(draw.indexCount, 1, draw.firstIndex, 0, 0))
					return error;
			}
			return {};
		}

		acm::Pipeline scenePipeline(const RendererState& renderer, const acm::RenderTarget& target)
		{
			acm::PipelineShaders shaders;
			shaders.vertex = renderer.sceneVertex;
			shaders.fragment = renderer.sceneFragment;
			acm::PipelineConfig config;
			config.vertexLayout = acm::VertexLayout{
				sizeof(Vertex),
				{
					{0, acm::Format::R32G32B32_Sfloat, offsetof(Vertex, position)},
					{1, acm::Format::R32G32B32_Sfloat, offsetof(Vertex, normal)},
					{2, acm::Format::R32G32_Sfloat, offsetof(Vertex, uv)},
				},
			};
			config.descriptorLayout = renderer.sceneLayout;
			config.depth = acm::DepthState::TestWrite(acm::CompareOp::Less);
			config.cullMode = acm::CullMode::None; // surfaces are seen from both sides
			return renderer.device->createPipeline(shaders, target, config);
		}
	} // namespace detail

