	Renderer::Renderer(acm::Device& device)
		: m(std::make_unique<detail::RendererState>())
	{
		m->device = &device;
		if (!device.valid())
		{
			m->problems.push_back("the device is not usable");
			return;
		}

		m->sceneLayout = device.createDescriptorSetLayout({
			{0, acm::DescriptorType::UniformBuffer, acm::ShaderStage::Vertex | acm::ShaderStage::Fragment},
			{1, acm::DescriptorType::UniformBufferDynamic, acm::ShaderStage::Vertex | acm::ShaderStage::Fragment},
			{2, acm::DescriptorType::UniformBuffer, acm::ShaderStage::Fragment},
			{3, acm::DescriptorType::CombinedImageSampler, acm::ShaderStage::Fragment},
			{4, acm::DescriptorType::StorageBuffer, acm::ShaderStage::Fragment},
		});
		m->lineLayout = device.createDescriptorSetLayout({
			{0, acm::DescriptorType::UniformBuffer, acm::ShaderStage::Vertex | acm::ShaderStage::Fragment},
			{1, acm::DescriptorType::StorageBuffer, acm::ShaderStage::Vertex},
		});
		m->sampler = device.createSampler();
		m->sceneVertex = device.createShader(sceneVert());
		m->sceneFragment = device.createShader(sceneFrag());
		m->lineVertex = device.createShader(linesVert());
		m->lineFragment = device.createShader(linesFrag());
		m->gridLayout = device.createDescriptorSetLayout({
			{0, acm::DescriptorType::UniformBuffer, acm::ShaderStage::Vertex | acm::ShaderStage::Fragment},
		});
		m->gridVertex = device.createShader(gridVert());
		m->gridFragment = device.createShader(gridFrag());
		m->captureLayout = device.createDescriptorSetLayout({
			{0, acm::DescriptorType::UniformBuffer, acm::ShaderStage::Compute},
			{1, acm::DescriptorType::UniformBuffer, acm::ShaderStage::Compute},
			{2, acm::DescriptorType::StorageImage, acm::ShaderStage::Compute},
			{3, acm::DescriptorType::StorageBuffer, acm::ShaderStage::Compute},
			{4, acm::DescriptorType::StorageBuffer, acm::ShaderStage::Compute},
		});
		m->captureShader = device.createShader(captureComp());
		m->capturePipeline = device.createComputePipeline(m->captureShader, m->captureLayout);

		// A pipeline is built against a target's formats, not its size, so a 1 x 1 one stands for
		// every view's.
		acm::Texture probe = device.createTexture(kColourFormat, acm::Extent2D{1, 1});
		acm::RenderTarget target = device.createRenderTarget(probe, acm::RenderTargetConfig{acm::RenderTargetFinish::CopySrc, true});
		if (target.valid())
			m->pipeline = detail::scenePipeline(*m, target);

		for (const acm::Error& error : {m->sceneLayout.error(), m->lineLayout.error(), m->sampler.error(), m->sceneVertex.error(),
										m->sceneFragment.error(), m->lineVertex.error(), m->lineFragment.error(), m->gridLayout.error(),
										m->gridVertex.error(), m->gridFragment.error(), target.error(),
										m->pipeline.error(), m->captureLayout.error(), m->captureShader.error(),
										m->capturePipeline.error()})
		{
			if (error)
			{
				m->problems.push_back("the device refused the renderer: " + error.message());
				return;
			}
		}
		if (!m->pipeline.valid())
			m->problems.push_back("the device refused the scene pipeline");
		else if (!m->capturePipeline.valid())
			m->problems.push_back("the device refused the capture pipeline");
	}

	Renderer::Renderer(Renderer&&) noexcept = default;
